// Shared 100 x 148 mm composition, matching the Imagination Hall reference.
export function calendarLayout(width,height,rotation=0,color='#000000',theme='default',qrUrl=''){
 if(!/^#[0-9a-f]{6}$/i.test(color))throw Error('Invalid calendar color');
 const commands=[],line='#'+[1,3,5].map(i=>Math.round(parseInt(color.slice(i,i+2),16)*.65+255*.35).toString(16).padStart(2,'0')).join('');
 const rotatedWidth=rotation===90?height:width,rotatedHeight=rotation===90?width:height;
 const topHeight=Math.min(1160,600*rotatedHeight/rotatedWidth),smallHeight=topHeight/2;
 const photo=(x,y,w,h)=>{const scale=Math.min(w/rotatedWidth,h/rotatedHeight),pw=rotatedWidth*scale;commands.push({type:'photo',x:x+(w-pw)/2,y,w:pw,h:rotatedHeight*scale,rotation});};
 photo(0,0,600,topHeight);photo(600,0,600,topHeight);
 photo(600,topHeight,300,smallHeight);photo(900,topHeight,300,smallHeight);
 const space=1776-topHeight,x=40,cw=524/7,y=topHeight+space*.36,rh=space*.54/6;
 const text=(value,x,y,size,font='condensed',align='left',maxWidth=Infinity)=>{
  const face=calendarFonts[font],width=[...value].reduce((n,c)=>n+face.glyphs[c].advance,0),scale=Math.min(size/face.units,maxWidth/width);
  let cursor=x-(align==='center'?width*scale/2:align==='right'?width*scale:0);const paths=[];
  for(const char of value){const glyph=face.glyphs[char];for(const cmd of glyph.path){const p=[cmd[0]];for(let i=1;i<cmd.length;i+=2)p.push(cursor+cmd[i]*scale,y-cmd[i+1]*scale);paths.push(p);}cursor+=glyph.advance*scale;}
  commands.push({type:'text',value,x,y,size,font,color,paths});
 };
 const rule=(x,y,w,h)=>commands.push({type:'line',x,y,w,h,color:line});
 text('OCT.',302,topHeight+space*(theme==='siwol'?.30:.27),220,theme==='siwol'?'siwol':'heading','center',524);
 rule(x,y-26,524,0);
 ['SUN','MON','TUE','WED','THU','FRI','SAT'].forEach((d,i)=>text(d,x+(i+.5)*cw,y-7,21,'condensed','center'));
 for(let i=0;i<=7;i++)rule(x+i*cw,y,0,rh*6);
 for(let i=0;i<=6;i++)rule(x,y+i*rh,cw*7,0);
 const first=new Date(Date.UTC(2026,9,1)).getUTCDay();
 for(let day=1;day<=31;day++){const n=first+day-1;text(String(day),x+(n%7+.5)*cw,y+(Math.floor(n/7)+.5)*rh+12,36,'condensed','center');}
 text('HELLO, OCTOBER!',40,topHeight+space*.943,25);text('2026',564,topHeight+space*.943,25,'condensed','right');
 const brandWidth=qrUrl?260:285,brandHeight=brandWidth*300/1220,captionY=(topHeight+smallHeight+1776)/2;
 commands.push({type:'brand',x:(qrUrl?800:900)-brandWidth/2,y:captionY-brandHeight/2,w:brandWidth,h:brandHeight,color,runs:brandRuns});
 if(qrUrl){
  const url=new URL(qrUrl);
  if(!['https:','http:'].includes(url.protocol)||url.pathname!=='/gallery.html'||!/^#[a-f0-9]{48}$/.test(url.hash))throw Error('Invalid photo QR URL');
  const qr=qrcode(0,'M');qr.addData(url.href);qr.make();const count=qr.getModuleCount(),unit=Math.max(.25,Math.min(4,196/(count+8),(1776-topHeight-smallHeight-12)/(count+8))),size=(count+8)*unit;
  const left=1168-size,top=captionY-size/2,rects=[];
  for(let row=0;row<count;row++)for(let col=0;col<count;col++)if(qr.isDark(row,col))rects.push([left+(col+4)*unit,top+(row+4)*unit,unit,unit]);
  commands.push({type:'qr',x:left,y:top,w:size,h:size,rects});
 }
 return commands;
}
const brandCache=new Map();
export function drawCalendar(canvas,image,scale=100,rotation=0,color='#000000',theme='default',qrUrl=''){
 canvas.width=1200;canvas.height=1776;const c=canvas.getContext('2d');c.fillStyle='#fff';c.fillRect(0,0,1200,1776);c.save();c.translate(600*(1-scale/100),888*(1-scale/100));c.scale(scale/100,scale/100);
 for(const p of calendarLayout(image.naturalWidth||image.width,image.naturalHeight||image.height,rotation,color,theme,qrUrl)){
  if(p.type==='photo'){c.save();if(p.rotation===90){c.translate(p.x+p.w,p.y);c.rotate(Math.PI/2);c.drawImage(image,0,0,p.h,p.w);}else c.drawImage(image,p.x,p.y,p.w,p.h);c.restore();}
  else if(p.type==='qr'){c.fillStyle='#fff';c.fillRect(p.x,p.y,p.w,p.h);c.fillStyle='#000';for(const rect of p.rects)c.fillRect(...rect);}
  else if(p.type==='brand'){let logo=brandCache.get(p.color);if(!logo){logo=document.createElement('canvas');logo.width=1220;logo.height=300;const lc=logo.getContext('2d');lc.fillStyle=p.color;for(const [x,y,w,a]of p.runs){lc.globalAlpha=a/255;lc.fillRect(x,y,w,1);}brandCache.set(p.color,logo);}c.drawImage(logo,p.x,p.y,p.w,p.h);}
  else if(p.type==='line'){c.strokeStyle=p.color;c.lineWidth=.8;c.beginPath();c.moveTo(p.x,p.y);c.lineTo(p.x+p.w,p.y+p.h);c.stroke();}
  else {c.fillStyle=p.color;c.beginPath();for(const [op,...v] of p.paths){if(op==='M')c.moveTo(...v);else if(op==='L')c.lineTo(...v);else if(op==='C')c.bezierCurveTo(...v);else if(op==='Z')c.closePath();}c.fill();}
 }c.restore();
}
